import { getNotificationStatus, toggleNotifications } from './actions';

export default async function Home() {
  const notificationsEnabled = await getNotificationStatus();

  return (
    <main className="p-8">
      <h1 className="text-2xl font-bold mb-4">Settings</h1>

      <div className="mb-6">
        <h2 className="text-xl mb-2">Notification Preferences</h2>
        <div className="flex items-center gap-4">
          <p>
            Status: <strong>{notificationsEnabled ? 'On' : 'Off'}</strong>
          </p>

          <form action={toggleNotifications}>
            <button 
              type="submit"
              className={`px-4 py-2 rounded ${
                notificationsEnabled 
                  ? 'bg-red-500 hover:bg-red-600 text-white' 
                  : 'bg-green-500 hover:bg-green-600 text-white'
              }`}
            >
              {notificationsEnabled ? 'Turn Off' : 'Turn On'}
            </button>
          </form>
        </div>
      </div>

      <p className="text-sm text-gray-500 mt-8">
        This preference is persisted in <code>app/data.json</code>.
      </p>
    </main>
  );
}

